import pandas as pd


def run(inputs: dict) -> dict:
    orders = inputs["orders"].copy()
    ref_customers = inputs["ref_customers"].copy()
    ref_skus = inputs["ref_skus"].copy()

    # Build lookup tables, first occurrence wins on duplicate keys
    cust_lookup = (
        ref_customers.drop_duplicates(subset="customer_id", keep="first")
        .set_index("customer_id")["status"]
    )

    sku_lookup = (
        ref_skus.drop_duplicates(subset="sku", keep="first")
        .set_index("sku")[["discontinued", "allowed_countries"]]
    )

    def evaluate(row):
        cust_id = row["customer_id"]
        # R1: customer unknown
        if pd.isna(cust_id) or cust_id not in cust_lookup.index:
            return "CUST_UNKNOWN"

        status = cust_lookup.loc[cust_id]
        # In case of unexpected duplicate index after drop_duplicates (shouldn't happen)
        if isinstance(status, pd.Series):
            status = status.iloc[0]

        # R2: customer inactive
        if pd.isna(status) or status != "ACTIVE":
            return "CUST_INACTIVE"

        sku = row["sku"]
        # R3: sku unknown
        if pd.isna(sku) or sku not in sku_lookup.index:
            return "SKU_UNKNOWN"

        disc = sku_lookup.loc[sku, "discontinued"]
        allowed = sku_lookup.loc[sku, "allowed_countries"]
        if isinstance(disc, pd.Series):
            disc = disc.iloc[0]
        if isinstance(allowed, pd.Series):
            allowed = allowed.iloc[0]

        # R4: sku discontinued
        if pd.notna(disc):
            try:
                disc_val = int(disc)
            except (ValueError, TypeError):
                disc_val = None
            if disc_val == 1:
                return "SKU_DISC"

        # R5: country whitelist check
        if pd.notna(allowed):
            allowed_str = str(allowed).strip()
            if allowed_str != "":
                members = [m.strip() for m in allowed_str.split(",")]
                members = [m for m in members if m != ""]
                ship_country = row["ship_country"]
                if pd.isna(ship_country) or ship_country not in members:
                    return "CTRY_BLOCKED"

        return None

    reason_codes = orders.apply(evaluate, axis=1)

    is_failure = reason_codes.notna()

    orders_clean = orders.loc[~is_failure].copy()

    orders_rejects = orders.loc[is_failure].copy()
    orders_rejects["reason_code"] = reason_codes.loc[is_failure]

    return {
        "orders_clean": orders_clean,
        "orders_rejects": orders_rejects,
    }
